UPDATE Units SET Maintenance='0' WHERE Maintenance='1';
UPDATE  Units SET BaseMoves= BaseMoves + 1 WHERE BaseMoves >0 AND UnitType NOT IN ('UNIT_GREAT_GENERAL', 'UNIT_GREAT_ENGINEER', 'UNIT_GREAT_MERCHANT', 'UNIT_GREAT_PROPHET', 'UNIT_GREAT_SCIENTIST', 'UNIT_GREAT_WRITER', 'UNIT_GREAT_ARTIST', 'UNIT_BUILDER', 'UNIT_TRADER', 'UNIT_SETTLER');